def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 99:
        return 'D'

    last_my, last_opp = history[-1]

    opp_c = sum(1 for a, b in history if b == 'C')
    opp_d = n - opp_c
    my_c = sum(1 for a, b in history if a == 'C')
    my_d = n - my_c

    opp_def_streak = 0
    for a, b in reversed(history):
        if b == 'D':
            opp_def_streak += 1
        else:
            break
    my_def_streak = 0
    for a, b in reversed(history):
        if a == 'D':
            my_def_streak += 1
        else:
            break

    if opp_d == n:
        return 'D'

    if n < 10:
        if last_opp == 'D':
            return 'D'
        return 'C'

    if opp_d == 0:
        known_forgiving = False
        for i in range(n - 1):
            if history[i][0] == 'D' and history[i + 1][1] == 'C':
                known_forgiving = True
                break
        if known_forgiving:
            return 'D'
        if my_d == 0:
            if n >= 15:
                return 'D'
            return 'C'
        if last_my == 'D':
            return 'C'
        last_def_idx = -1
        for i in range(n - 1, -1, -1):
            if history[i][0] == 'D':
                last_def_idx = i
                break
        if last_def_idx != -1 and last_def_idx + 1 < n:
            if history[last_def_idx + 1][1] == 'D':
                return 'C'
        return 'C'

    if opp_def_streak >= 3 and my_def_streak >= 3 and n < 95:
        return 'C'

    recent = history[-10:] if n >= 10 else history
    recent_opp_d = sum(1 for a, b in recent if b == 'D')

    if last_opp == 'D':
        if opp_c / n > 0.8 and recent_opp_d <= 2:
            return 'C'
        if last_my == 'D' and n > 20 and opp_c / n > 0.6:
            return 'C'
        if opp_c / n > 0.4 and n < 95 and rng.random() < 0.25:
            return 'C'
        return 'D'

    if recent_opp_d >= 5:
        return 'D'
    if recent_opp_d <= 1:
        return 'C'
    return 'C'
